// 导入axios实例
import httpRequest from "@/apis/axios-api";
import httpRequestCommon from "@/apis/axios-common";
import { UploadImageTokenResponse } from "@/util/md-editor-v3.ts";
import type {BannerItem, JudgeStatus, FriendLink } from "@/types/system.ts";

export function GetWebNotification() {
  return httpRequestCommon({
    baseURL: "https://r2-oj.didapipa.com",
    url: "/system/notification.json" + "?" + Date.now(),
    method: "get",
  });
}

export function GetWebAnnouncement() {
  return httpRequestCommon({
    baseURL: "https://r2-oj.didapipa.com",
    url: "/system/announcement.json" + "?" + Date.now(),
    method: "get",
  });
}

export function GetWebBanners(): Promise<{
  code: number;
  data?: { images: BannerItem[] };
  images?: BannerItem[];
}> {
  return httpRequestCommon({
    baseURL: "https://r2-oj.didapipa.com",
    url: "/system/banner.json" + "?" + Date.now(),
    method: "get",
  });
}

export function GetSystemStatus() {
  return httpRequest({
    url: "/system/status",
    method: "get",
  });
}

export function GetSystemImageToken(): Promise<UploadImageTokenResponse> {
  return httpRequest({
    url: "/system/image/token",
    method: "get",
  });
}

export function GetBannerImageToken(): Promise<UploadImageTokenResponse> {
  return httpRequest({
    url: "/system/banner/image/token",
    method: "get",
  });
}

export function PostNotificationSave(theme: string, content: string) {
  return httpRequest({
    url: "/system/notification",
    method: "post",
    data: {
      theme: theme,
      content: content,
    },
  });
}

export function PostAnnouncementSave(title: string, content: string) {
  return httpRequest({
    url: "/system/announcement",
    method: "post",
    data: {
      title: title,
      content: content,
    },
  });
}

export function PostBannerSave(images: BannerItem[]) {
  return httpRequest({
    url: "/system/banner",
    method: "post",
    data: {
      images: images,
    },
  });
}

export function GetJudgeStatusList(): Promise<{ code: number; data: JudgeStatus[] }> {
  return httpRequest({
    url: "/system/judge/status/list",
    method: "get",
  });
}

export function PostJudgeStatusList(list: JudgeStatus[]) {
  return httpRequest({
    url: "/system/judge/status/list",
    method: "post",
    data: { list },
  });
}

export function GetFriendLinkList(): Promise<{ code: number; data: FriendLink[] }> {
  return httpRequest({
    url: "/system/friend/link/list",
    method: "get",
  });
}

export function PostFriendLinkList(list: FriendLink[]) {
  return httpRequest({
    url: "/system/friend/link/list",
    method: "post",
    data: { list },
  });
}
